CREATE OR REPLACE FUNCTION public.booking_notification_attempt_state_valid()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE d booking_notification_deliveries%ROWTYPE; a booking_notification_attempts%ROWTYPE; target uuid;
BEGIN
 IF TG_TABLE_NAME='booking_notification_deliveries' THEN target=NEW.id;
 ELSIF TG_TABLE_NAME='booking_notification_attempts' THEN target=NEW.delivery_id;
 ELSE SELECT delivery_id INTO target FROM booking_notification_attempts WHERE id=NEW.attempt_id; END IF;
 SELECT * INTO d FROM booking_notification_deliveries WHERE id=target FOR UPDATE;
 IF d.attempt_count<>(SELECT count(*) FROM booking_notification_attempts WHERE delivery_id=target)
 THEN RAISE EXCEPTION 'booking_notification_attempt_count_invalid'; END IF;
 IF d.attempt_count>0 THEN
  SELECT * INTO a FROM booking_notification_attempts WHERE delivery_id=target AND ordinal=d.attempt_count;
  IF NOT FOUND OR a.bot_key IS DISTINCT FROM d.bot_key OR
    (d.external_chat_id IS NOT NULL AND a.chat_id IS DISTINCT FROM d.external_chat_id)
  THEN RAISE EXCEPTION 'booking_notification_attempt_binding_invalid'; END IF;
 END IF;
 IF d.state='sending' AND (a.id IS NULL OR a.claim_token IS DISTINCT FROM d.lease_token OR EXISTS(SELECT 1 FROM booking_notification_attempt_facts WHERE attempt_id=a.id))
 THEN RAISE EXCEPTION 'booking_notification_sending_invalid'; END IF;
 IF d.state='delivered' AND NOT EXISTS(SELECT 1 FROM booking_notification_attempt_facts WHERE attempt_id=a.id AND outcome='applied')
 THEN RAISE EXCEPTION 'booking_notification_receipt_required'; END IF;
 IF d.state IN ('unknown','manual') AND NOT EXISTS(SELECT 1 FROM booking_notification_attempt_facts WHERE attempt_id=a.id AND outcome='unknown')
 THEN RAISE EXCEPTION 'booking_notification_uncertainty_required'; END IF;
 RETURN NULL;
END $function$

CREATE OR REPLACE FUNCTION public.client_booking_guard_privacy_completion()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF NEW.status IN ('processor_complete','backup_verified')
     AND EXISTS (
       SELECT 1 FROM client_booking_erasure_work w
       WHERE w.deletion_job_id=NEW.id AND w.phase <> 'complete'
     ) THEN
    RAISE EXCEPTION 'client_booking_erasure_incomplete' USING ERRCODE='23514';
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.enforce_admin_ledger_provenance()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
  package_row "message_packages"%ROWTYPE;
  original_grant "message_ledger_entries"%ROWTYPE;
BEGIN
  IF NEW.legacy_admin_fact THEN
    RAISE EXCEPTION 'legacy admin ledger marker is migration-only' USING ERRCODE = '23514';
  END IF;
  SELECT * INTO package_row
  FROM "message_packages"
  WHERE "id" = NEW."package_id";
  IF NOT FOUND THEN
    RETURN NEW;
  END IF;
  IF package_row."kind" = 'paid' THEN
    IF NEW."admin_approval_id" IS NOT NULL OR NEW."admin_requester_session_id_hash" IS NOT NULL THEN
      RAISE EXCEPTION 'paid ledger facts cannot carry admin approval provenance' USING ERRCODE = '23514';
    END IF;
    RETURN NEW;
  END IF;
  IF package_row."legacy_admin_grant" THEN
    IF NEW."entry_kind" IN ('grant', 'revocation') THEN
      RAISE EXCEPTION 'legacy admin entitlements cannot receive new admin grant or revocation facts' USING ERRCODE = '23514';
    END IF;
    RETURN NEW;
  END IF;
  IF NEW."entry_kind" = 'grant' AND (
    NEW."admin_approval_id" IS DISTINCT FROM package_row."admin_approval_id"
    OR NEW."admin_requester_session_id_hash" IS DISTINCT FROM package_row."admin_requester_session_id_hash"
  ) THEN
    RAISE EXCEPTION 'admin grant provenance must match package provenance' USING ERRCODE = '23514';
  END IF;
  IF NEW."entry_kind" = 'revocation' THEN
    IF NEW."admin_approval_id" IS NULL OR NEW."admin_requester_session_id_hash" IS NULL THEN
      RAISE EXCEPTION 'admin revocation provenance is required' USING ERRCODE = '23514';
    END IF;
    SELECT * INTO original_grant
    FROM "message_ledger_entries"
    WHERE "id" = NEW."original_entry_id"
      AND "package_id" = NEW."package_id"
      AND "entry_kind" = 'grant';
    IF NOT FOUND
      OR original_grant."admin_approval_id" IS DISTINCT FROM package_row."admin_approval_id"
      OR original_grant."admin_requester_session_id_hash" IS DISTINCT FROM package_row."admin_requester_session_id_hash"
    THEN
      RAISE EXCEPTION 'admin revocation original grant provenance is invalid' USING ERRCODE = '23514';
    END IF;
    IF NOT EXISTS (
      SELECT 1
      FROM "admin_approvals" a
      WHERE a."id" = NEW."admin_approval_id"
        AND a."requester_session_id_hash" = NEW."admin_requester_session_id_hash"
        AND a."action" = 'package.revoke'
        AND a."object_type" = 'user'
        AND a."object_id" = package_row."user_id"
        AND a."required_role" = 'entitlement_admin'
        AND a."payload_hash" = 'sha256:' || encode(digest(convert_to(
          '{"idempotencyKey":' || to_json(NEW."idempotency_key")::text ||
          ',"packageId":' || to_json(NEW."package_id"::text)::text ||
          ',"userId":' || to_json(package_row."user_id"::text)::text || '}',
          'UTF8'
        ), 'sha256'), 'hex')
        AND a."consumed_at" IS NOT NULL
    ) THEN
      RAISE EXCEPTION 'admin revocation approval provenance is invalid' USING ERRCODE = '23514';
    END IF;
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.enforce_admin_package_provenance()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
  expected_action text;
  expected_payload_hash text;
BEGIN
  IF NEW.legacy_admin_grant THEN
    RAISE EXCEPTION 'legacy admin package marker is migration-only' USING ERRCODE = '23514';
  END IF;
  IF NEW.kind = 'paid' THEN
    RETURN NEW;
  END IF;
  expected_action := CASE WHEN NEW.kind = 'admin' THEN 'package.grant' ELSE 'package.intro_grant' END;
  expected_payload_hash := 'sha256:' || encode(digest(convert_to(
    '{"idempotencyKey":' || to_json(NEW.grant_idempotency_key)::text ||
    ',"units":' || NEW.granted_messages::text ||
    ',"userId":' || to_json(NEW.user_id::text)::text || '}',
    'UTF8'
  ), 'sha256'), 'hex');
  IF NOT EXISTS (
    SELECT 1
    FROM "admin_approvals" a
    WHERE a."id" = NEW."admin_approval_id"
      AND a."requester_session_id_hash" = NEW."admin_requester_session_id_hash"
      AND a."action" = expected_action
      AND a."object_type" = 'user'
      AND a."object_id" = NEW."user_id"
      AND a."required_role" = 'entitlement_admin'
      AND a."payload_hash" = expected_payload_hash
      AND a."consumed_at" IS NOT NULL
  ) THEN
    RAISE EXCEPTION 'admin package approval provenance is invalid' USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.enforce_client_coupon_purchase()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM client_paid_orders o WHERE o.id = NEW.order_id
    AND o.mode = 'live' AND o.user_id = NEW.user_id AND o.coupon_grant_minor = NEW.amount_minor
    AND NEW.captured_at >= o.created_at) THEN
    RAISE EXCEPTION 'client coupon purchase mismatch' USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.enforce_expert_application_identity_immutable()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF NEW.user_id IS DISTINCT FROM OLD.user_id OR NEW.campaign_quote_id IS DISTINCT FROM OLD.campaign_quote_id THEN
    RAISE EXCEPTION 'expert_application_identity_immutable' USING ERRCODE='23514';
  END IF;
  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.enforce_expert_campaign_order_source()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
  quote expert_campaign_quotes%ROWTYPE;
  tariff expert_residency_tariff_versions%ROWTYPE;
  expert experts%ROWTYPE;
  checked_at timestamptz;
BEGIN
  IF NEW.commercial_policy_version <> 'expert_campaign_v1' THEN RETURN NEW; END IF;
  SELECT * INTO quote FROM expert_campaign_quotes WHERE id=NEW.campaign_quote_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'expert_campaign_order_source' USING ERRCODE='23514';
  END IF;
  LOCK TABLE consent_document_versions IN SHARE MODE;
  PERFORM pg_advisory_xact_lock(hashtextextended(quote.user_id::text,0));
  PERFORM 1 FROM users WHERE id=quote.user_id AND active=true FOR SHARE;
  IF NOT FOUND THEN RAISE EXCEPTION 'expert_campaign_order_source' USING ERRCODE='23514'; END IF;
  SELECT * INTO expert FROM experts WHERE id=NEW.expert_id FOR SHARE;
  IF NOT FOUND OR expert.user_id IS DISTINCT FROM quote.user_id OR (
    (NOT expert.active OR NOT expert.verified) AND NOT EXISTS(
      SELECT 1 FROM expert_card_main_acceptances a WHERE a.expert_id=NEW.expert_id AND a.user_id=quote.user_id
        AND a.quote_id=quote.id AND a.application_id IS NOT NULL AND a.review_id IS NOT NULL
        AND expert_card_activation_gate_valid(a.user_id,a.review_id))) THEN
    RAISE EXCEPTION 'expert_campaign_order_source' USING ERRCODE='23514';
  END IF;
  PERFORM 1 FROM expert_campaign_quotes WHERE id=quote.id FOR SHARE;
  SELECT * INTO tariff FROM expert_residency_tariff_versions WHERE id=quote.tariff_version_id FOR SHARE;
  checked_at := clock_timestamp();
  IF checked_at < quote.quoted_at OR checked_at >= quote.expires_at THEN
    RAISE EXCEPTION 'expert_campaign_order_expired' USING ERRCODE='23514',CONSTRAINT='expert_campaign_order_expired';
  END IF;
  IF NOT FOUND OR tariff.commercial_policy_version <> 'expert_residency_v2'
    OR checked_at < tariff.active_from OR checked_at >= tariff.active_to
    OR NEW.created_at < quote.quoted_at OR NEW.created_at > checked_at
    OR NEW.provider_deadline IS DISTINCT FROM quote.expires_at
    OR NOT isfinite(NEW.created_at) OR NOT isfinite(NEW.payment_deadline)
    OR ROW(NEW.tariff_version_id,NEW.campaign_term_months,NEW.snapshot_display_name,NEW.price_minor,NEW.currency,
      NEW.duration_seconds,NEW.credit_cap_bps,NEW.individual_services_enabled,NEW.group_event_limit,NEW.statistics_level,NEW.support_priority)
      IS DISTINCT FROM ROW(quote.tariff_version_id,quote.term_months,quote.display_name,quote.price_minor,quote.currency,
      quote.duration_seconds,quote.credit_cap_bps,quote.individual_services_enabled,quote.group_event_limit,quote.statistics_level,quote.support_priority)
  THEN RAISE EXCEPTION 'expert_campaign_order_source' USING ERRCODE='23514'; END IF;
  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.enforce_expert_campaign_quote_source()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
  tariff expert_residency_tariff_versions%ROWTYPE;
  stage_end timestamptz;
  expected_expiry timestamptz;
BEGIN
  LOCK TABLE consent_document_versions IN SHARE MODE;
  PERFORM pg_advisory_xact_lock(hashtextextended(NEW.user_id::text,0));
  PERFORM 1 FROM users WHERE id=NEW.user_id AND active=true FOR SHARE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'expert_campaign_source_invalid' USING ERRCODE='23514';
  END IF;
  SELECT * INTO tariff FROM expert_residency_tariff_versions WHERE id=NEW.tariff_version_id FOR SHARE;
  IF NOT FOUND OR tariff.commercial_policy_version <> 'expert_residency_v2'
    OR NOT isfinite(NEW.quoted_at) OR NEW.quoted_at < tariff.active_from OR NEW.quoted_at >= tariff.active_to
    OR ROW(NEW.base_monthly_minor,NEW.currency,NEW.display_name,NEW.credit_cap_bps,
      NEW.individual_services_enabled,NEW.group_event_limit,NEW.statistics_level,NEW.support_priority)
      IS DISTINCT FROM ROW(tariff.price_minor,tariff.currency,tariff.display_name,tariff.credit_cap_bps,
      tariff.individual_services_enabled,tariff.group_event_limit,tariff.statistics_level,tariff.support_priority)
    OR tariff.duration_seconds <> 2592000 THEN
    RAISE EXCEPTION 'expert_campaign_source_invalid' USING ERRCODE='23514';
  END IF;
  stage_end := CASE
    WHEN NEW.quoted_at - NEW.calculation_timestamp < interval '72 hours' THEN NEW.calculation_timestamp + interval '72 hours'
    WHEN NEW.quoted_at - NEW.calculation_timestamp < interval '144 hours' THEN NEW.calculation_timestamp + interval '144 hours'
    WHEN NEW.quoted_at - NEW.calculation_timestamp < interval '216 hours' THEN NEW.calculation_timestamp + interval '216 hours'
    ELSE 'infinity'::timestamptz END;
  expected_expiry := least(NEW.quoted_at + interval '15 minutes',date_trunc('milliseconds',tariff.active_to),stage_end);
  IF NEW.expires_at IS DISTINCT FROM expected_expiry THEN
    RAISE EXCEPTION 'expert_campaign_expiry_invalid' USING ERRCODE='23514';
  END IF;
  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.enforce_expert_referral_admin_approval_global_unique()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE lock_key bigint;
BEGIN
  FOR lock_key IN SELECT DISTINCT hashtextextended(value::text, 928451) AS advisory_key FROM unnest(array[NEW.approval_id,NEW.second_approval_id]) AS approvals(value) WHERE value is not null ORDER BY advisory_key LOOP
    PERFORM pg_advisory_xact_lock(lock_key);
  END LOOP;
  IF EXISTS (SELECT 1 FROM expert_referral_admin_execution_results existing WHERE existing.approval_id in (NEW.approval_id,NEW.second_approval_id) OR existing.second_approval_id in (NEW.approval_id,NEW.second_approval_id)) THEN
    RAISE EXCEPTION USING ERRCODE='23505', MESSAGE='expert_referral_admin_approval_global_unique';
  END IF;
  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.expert_first_settlement_guard_change()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION USING ERRCODE='55000', CONSTRAINT='expert_first_settlement_transition', MESSAGE='expert_first_settlement_guard';
  END IF;
  IF NOT (
      (OLD.eligibility = 'pending_feature_hold' AND NEW.eligibility IN ('eligible','permanently_ineligible','cancelled_by_refund'))
      OR (OLD.eligibility = 'eligible' AND NEW.eligibility = 'cancelled_by_refund')
    )
    OR ROW(NEW.id,NEW.expert_id,NEW.settlement_sequence,NEW.qualifying_order_id,NEW.qualifying_payment_attempt_id,NEW.referral_id,NEW.settlement_expert_active,NEW.settlement_expert_verified,NEW.settlement_abuse_cleared,NEW.settlement_control_version,NEW.settlement_invitee_user_id,NEW.settlement_invitee_channel_identity_id,NEW.settlement_inviter_expert_id,NEW.settlement_inviter_user_id,NEW.settlement_inviter_channel_identity_id,NEW.settled_at,NEW.created_at)
       IS DISTINCT FROM
       ROW(OLD.id,OLD.expert_id,OLD.settlement_sequence,OLD.qualifying_order_id,OLD.qualifying_payment_attempt_id,OLD.referral_id,OLD.settlement_expert_active,OLD.settlement_expert_verified,OLD.settlement_abuse_cleared,OLD.settlement_control_version,OLD.settlement_invitee_user_id,OLD.settlement_invitee_channel_identity_id,OLD.settlement_inviter_expert_id,OLD.settlement_inviter_user_id,OLD.settlement_inviter_channel_identity_id,OLD.settled_at,OLD.created_at)
  THEN
    RAISE EXCEPTION USING ERRCODE='55000', CONSTRAINT='expert_first_settlement_transition', MESSAGE='expert_first_settlement_guard';
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.expert_provider_reversal_result_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF TG_OP='INSERT' AND NEW.result_legacy_exempt THEN
    RAISE EXCEPTION USING ERRCODE='23514', CONSTRAINT='expert_provider_reversal_legacy_exempt_forbidden', MESSAGE='expert_provider_reversal_legacy_exempt_forbidden';
  END IF;
  IF TG_OP='UPDATE' AND NEW.result_legacy_exempt AND NOT OLD.result_legacy_exempt THEN
    RAISE EXCEPTION USING ERRCODE='23514', CONSTRAINT='expert_provider_reversal_legacy_exempt_forbidden', MESSAGE='expert_provider_reversal_legacy_exempt_forbidden';
  END IF;
  IF TG_OP='INSERT' THEN
    RETURN NEW;
  END IF;
  IF OLD.status='processed' AND OLD.event_kind IN ('refunded','charged_back')
     AND (NEW.result_payload IS DISTINCT FROM OLD.result_payload OR NEW.result_schema_version IS DISTINCT FROM OLD.result_schema_version OR NEW.result_legacy_exempt IS DISTINCT FROM OLD.result_legacy_exempt)
  THEN
    RAISE EXCEPTION USING ERRCODE='55000', CONSTRAINT='expert_provider_reversal_result_immutable', MESSAGE='expert_provider_reversal_result_immutable';
  END IF;
  IF NEW.status='processed' AND NEW.event_kind IN ('refunded','charged_back')
     AND OLD.status IS DISTINCT FROM 'processed' AND (NEW.result_schema_version IS DISTINCT FROM 1 OR NEW.result_legacy_exempt)
  THEN
    RAISE EXCEPTION USING ERRCODE='23514', CONSTRAINT='expert_provider_reversal_result_required', MESSAGE='expert_provider_reversal_result_required';
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.expert_referral_maturities_append_only_terminal()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF OLD.status IN ('granted', 'cancelled') THEN RAISE EXCEPTION 'expert_referral_maturities_terminal_immutable' USING ERRCODE = '23514'; END IF;
  IF NEW.status IN ('granted', 'cancelled') AND (NEW.settled_at <> OLD.settled_at OR NEW.matures_at <> OLD.matures_at OR NEW.first_settlement_id <> OLD.first_settlement_id OR NEW.referral_id <> OLD.referral_id OR NEW.qualifying_order_id <> OLD.qualifying_order_id OR NEW.qualifying_payment_attempt_id <> OLD.qualifying_payment_attempt_id OR NEW.inviter_expert_id <> OLD.inviter_expert_id) THEN
    RAISE EXCEPTION 'expert_referral_maturities_financial_facts_immutable' USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END; $function$

CREATE OR REPLACE FUNCTION public.expert_referral_validate_ledger_allocation_total()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
  target_entry_id uuid;
  expected_total bigint;
  allocated_total bigint;
BEGIN
  IF TG_TABLE_NAME = 'expert_referral_ledger_entries' THEN
    target_entry_id := CASE WHEN TG_OP = 'DELETE' THEN OLD.id ELSE NEW.id END;
  ELSE
    target_entry_id := CASE WHEN TG_OP = 'DELETE' THEN OLD.ledger_entry_id ELSE NEW.ledger_entry_id END;
  END IF;

  SELECT amount_minor
    INTO expected_total
    FROM expert_referral_ledger_entries
    WHERE id = target_entry_id;

  IF NOT FOUND THEN
    RETURN NULL;
  END IF;

  SELECT coalesce(sum(amount_minor), 0)::bigint
    INTO allocated_total
    FROM expert_referral_ledger_allocations
    WHERE ledger_entry_id = target_entry_id;

  IF allocated_total <> expected_total THEN
    RAISE EXCEPTION USING
      ERRCODE = '23514',
      CONSTRAINT = 'expert_ledger_allocations_exact_total',
      MESSAGE = 'expert_ledger_allocations_exact_total';
  END IF;

  RETURN NULL;
END;
$function$

CREATE OR REPLACE FUNCTION public.expert_residency_default_provider_deadline()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF NEW.provider_deadline IS NULL THEN
    NEW.provider_deadline := NEW.payment_deadline;
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.lock_and_reject_selarti_budget_policy_overlap()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  PERFORM pg_advisory_xact_lock(739184, 42036);
  IF EXISTS (
    SELECT 1 FROM selarti_budget_policies p
    WHERE p.status='approved' AND tstzrange(p.effective_from, p.effective_to, '[)') &&
      tstzrange(NEW.effective_from, NEW.effective_to, '[)')
  ) THEN RAISE EXCEPTION 'selarti budget policy window overlaps approved policy'; END IF;
  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.lock_partner_policy_window()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF NEW.status='approved' THEN
    PERFORM pg_advisory_xact_lock(739184, 42037);
    IF EXISTS (SELECT 1 FROM partner_tariff_policy_versions p WHERE p.status='approved' AND p.partner_kind=NEW.partner_kind AND p.id<>NEW.id AND tstzrange(p.effective_from,p.effective_to,'[)') && tstzrange(NEW.effective_from,NEW.effective_to,'[)')) THEN
      RAISE EXCEPTION 'partner tariff policy window overlaps approved policy' USING ERRCODE='23514';
    END IF;
  END IF;
  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.planerka_reservation_transition()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF NEW.status = 'booked' AND OLD.status <> 'booked' AND NOT EXISTS (
    SELECT 1 FROM planerka_booking_operations WHERE reservation_id=NEW.id AND state='booked' AND provider_uid IS NOT NULL AND NOT cancel_requested
  ) THEN RAISE EXCEPTION 'planerka_confirmation_required'; END IF;
  IF NEW.status IN ('cancelled_by_client','cancelled_by_expert','expired') AND NEW.status IS DISTINCT FROM OLD.status THEN
    UPDATE planerka_booking_operations SET cancel_requested=true,
      state=CASE WHEN state='pending' THEN 'cancelled' WHEN state='booked' THEN 'cancel_pending' ELSE state END,
      next_attempt_at=clock_timestamp(),updated_at=clock_timestamp()
    WHERE reservation_id=NEW.id;
  END IF;
  IF NEW.status IN ('completed','no_show') AND OLD.status='booked' THEN
    UPDATE planerka_booking_operations SET state='finished',updated_at=clock_timestamp()
      WHERE reservation_id=NEW.id AND state='booked';
  END IF;
  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.protect_expert_campaign_order_snapshot()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF TG_OP='DELETE' THEN
    IF OLD.commercial_policy_version='expert_campaign_v1' OR OLD.campaign_quote_id IS NOT NULL THEN
      RAISE EXCEPTION 'expert_campaign_order_immutable' USING ERRCODE='23514';
    END IF;
    RETURN OLD;
  END IF;
  IF OLD.commercial_policy_version='expert_campaign_v1' OR NEW.commercial_policy_version='expert_campaign_v1'
    OR OLD.campaign_quote_id IS NOT NULL OR NEW.campaign_quote_id IS NOT NULL THEN
    IF (to_jsonb(NEW) - ARRAY['status','provider_payment_id','settled_at','residency_starts_at','residency_ends_at','updated_at'])
      IS DISTINCT FROM (to_jsonb(OLD) - ARRAY['status','provider_payment_id','settled_at','residency_starts_at','residency_ends_at','updated_at']) THEN
      RAISE EXCEPTION 'expert_campaign_order_immutable' USING ERRCODE='23514';
    END IF;
  END IF;
  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.protect_expert_residency_renewal_attempt()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE bill expert_residency_renewal_bills%ROWTYPE; prior expert_residency_renewal_attempts%ROWTYPE;
BEGIN
 IF TG_OP<>'INSERT' THEN RAISE EXCEPTION 'residency_attempt_immutable' USING ERRCODE='23514'; END IF;
 SELECT * INTO bill FROM expert_residency_renewal_bills WHERE id=NEW.bill_id FOR UPDATE;
 IF NOT FOUND OR bill.user_id IS NULL OR bill.quote_id IS DISTINCT FROM NEW.quote_id OR bill.acceptance_id IS DISTINCT FROM NEW.acceptance_id THEN RAISE EXCEPTION 'residency_attempt_bill' USING ERRCODE='23514'; END IF;
 SELECT * INTO prior FROM expert_residency_renewal_attempts WHERE bill_id=NEW.bill_id ORDER BY sequence DESC LIMIT 1;
 IF NEW.sequence<>coalesce(prior.sequence,0)+1 OR (prior.order_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM expert_residency_orders WHERE id=prior.order_id AND status='expired' AND payment_deadline<=clock_timestamp())) OR NOT EXISTS(SELECT 1 FROM expert_card_main_orders m JOIN expert_residency_orders o ON o.id=m.order_id WHERE m.order_id=NEW.order_id AND m.acceptance_id=NEW.acceptance_id AND m.user_id=bill.user_id AND m.expert_id=bill.expert_id AND o.campaign_quote_id=NEW.quote_id AND o.id<>bill.source_order_id AND o.created_at>=bill.created_at AND o.status='payment_pending' AND o.payment_deadline>clock_timestamp()) THEN RAISE EXCEPTION 'residency_attempt_source' USING ERRCODE='23514'; END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.protect_expert_residency_renewal_bill()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF TG_OP='UPDATE' AND ((NEW.expert_id,NEW.owner_audit_id,NEW.cycle_end,NEW.source_order_id,NEW.created_at) IS DISTINCT FROM (OLD.expert_id,OLD.owner_audit_id,OLD.cycle_end,OLD.source_order_id,OLD.created_at)
 OR (OLD.order_id IS NOT NULL AND NEW.order_id IS DISTINCT FROM OLD.order_id)
 OR (NEW.user_id IS DISTINCT FROM OLD.user_id AND NEW.user_id IS NOT NULL)) THEN RAISE EXCEPTION 'residency_bill_immutable' USING ERRCODE='23514'; END IF;
 IF TG_OP='UPDATE' AND (NEW.quote_id,NEW.acceptance_id,NEW.tariff_version_id,NEW.term_months) IS DISTINCT FROM (OLD.quote_id,OLD.acceptance_id,OLD.tariff_version_id,OLD.term_months) AND EXISTS(SELECT 1 FROM expert_residency_renewal_attempts a JOIN expert_residency_orders o ON o.id=a.order_id WHERE a.bill_id=OLD.id AND NOT(o.status='expired' AND o.payment_deadline<=clock_timestamp())) THEN RAISE EXCEPTION 'residency_attempt_recovery_required' USING ERRCODE='23514'; END IF;
 IF TG_OP='INSERT' AND (NEW.user_id IS NULL OR NOT EXISTS(SELECT 1 FROM users WHERE id=NEW.user_id AND active)) THEN RAISE EXCEPTION 'residency_bill_live_owner_required' USING ERRCODE='23514'; END IF;
 IF TG_OP='UPDATE' AND OLD.user_id IS NOT NULL AND NEW.user_id IS NULL AND EXISTS(SELECT 1 FROM users WHERE id=OLD.user_id AND active) THEN RAISE EXCEPTION 'residency_bill_erasure_required' USING ERRCODE='23514'; END IF;
 IF (NEW.user_id IS NOT NULL AND NEW.user_id IS DISTINCT FROM NEW.owner_audit_id) OR NOT EXISTS(SELECT 1 FROM experts e JOIN expert_residency_orders o ON o.expert_id=e.id WHERE e.id=NEW.expert_id AND NEW.owner_audit_id=e.user_id AND o.id=NEW.source_order_id AND o.residency_ends_at=NEW.cycle_end AND (TG_OP<>'INSERT' OR o.status='settled')) THEN RAISE EXCEPTION 'residency_bill_source' USING ERRCODE='23514'; END IF;
 IF NEW.quote_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM expert_campaign_quotes q WHERE q.id=NEW.quote_id AND q.user_id=NEW.owner_audit_id AND q.tariff_version_id=NEW.tariff_version_id AND q.term_months=NEW.term_months) THEN RAISE EXCEPTION 'residency_bill_quote' USING ERRCODE='23514'; END IF;
 IF NEW.acceptance_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM expert_card_main_acceptances a WHERE a.id=NEW.acceptance_id AND a.user_id=NEW.owner_audit_id AND a.expert_id=NEW.expert_id AND a.quote_id=NEW.quote_id) THEN RAISE EXCEPTION 'residency_bill_acceptance' USING ERRCODE='23514'; END IF;
 IF NEW.order_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM expert_card_main_orders m WHERE m.order_id=NEW.order_id AND m.expert_id=NEW.expert_id AND m.user_id=NEW.owner_audit_id AND EXISTS(SELECT 1 FROM expert_residency_renewal_attempts first_attempt WHERE first_attempt.bill_id=NEW.id AND first_attempt.sequence=1 AND first_attempt.order_id=NEW.order_id AND first_attempt.acceptance_id=m.acceptance_id)) THEN RAISE EXCEPTION 'residency_bill_order' USING ERRCODE='23514'; END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.protect_payer_receipt_binding()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE contact payer_receipt_contacts%ROWTYPE;
BEGIN
  IF TG_OP<>'INSERT' THEN RAISE EXCEPTION 'payer_receipt_binding_immutable' USING ERRCODE='23514'; END IF;
  SELECT * INTO contact FROM payer_receipt_contacts WHERE id=NEW.contact_id FOR UPDATE;
  IF NOT FOUND OR contact.redacted_at IS NOT NULL OR contact.expires_at<=clock_timestamp() THEN
    RAISE EXCEPTION 'payer_receipt_unavailable' USING ERRCODE='23514';
  END IF;
  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.validate_and_consume_selarti_budget_approval()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE approval admin_approvals%ROWTYPE; expected_hash text;
BEGIN
  PERFORM pg_advisory_xact_lock(739184, 42036);
  expected_hash := 'sha256:' || encode(digest(convert_to(to_json(concat_ws('|','selarti-budget-policy-v1',NEW.version,NEW.status,to_char(NEW.effective_from at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'),coalesce(to_char(NEW.effective_to at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'),'-'),NEW.global_cap_rub_minor,NEW.global_warning_rub_minor,NEW.global_soft_rub_minor,NEW.per_user_warning_rub_minor,NEW.per_user_soft_rub_minor,NEW.per_user_hard_rub_minor,NEW.official_usd_rub_quote_micros,NEW.selarti_uplift_bps,NEW.usd_micros_per_request,NEW.usd_micros_per_unit,NEW.worst_case_billable_units,NEW.rate_version,NEW.model_version,NEW.stress_inflation_bps))::text,'UTF8'),'sha256'),'hex');
  SELECT * INTO approval FROM admin_approvals WHERE id=NEW.approval_id FOR UPDATE;
  IF approval.id IS NULL OR approval.action<>'selarti_budget.policy_approve' OR approval.object_type<>'selarti_budget_policy' OR approval.object_id<>NEW.id OR approval.required_role<>'security_admin' OR approval.requester_id=approval.approver_id OR approval.approver_id IS NULL OR approval.requester_session_id_hash IS NULL OR approval.requester_mfa_verified_at IS NULL OR approval.approver_session_id_hash IS NULL OR approval.approver_mfa_verified_at IS NULL OR approval.approved_at IS NULL OR approval.approved_at>NEW.created_at OR approval.consumed_at IS NOT NULL OR approval.expires_at<=NEW.created_at OR approval.payload_hash<>expected_hash OR approval.requester_mfa_verified_at < NEW.created_at - interval '15 minutes' OR approval.requester_mfa_verified_at > NEW.created_at OR approval.approver_mfa_verified_at < NEW.created_at - interval '15 minutes' OR approval.approver_mfa_verified_at > NEW.created_at OR NOT EXISTS (SELECT 1 FROM admin_sessions s JOIN admin_role_assignments r ON r.admin_id=s.admin_id AND r.role='security_admin' WHERE s.session_id_hash=approval.requester_session_id_hash AND s.admin_id=approval.requester_id AND s.mfa_verified_at=approval.requester_mfa_verified_at AND s.revoked_at IS NULL AND s.expires_at>NEW.created_at) OR NOT EXISTS (SELECT 1 FROM admin_sessions s JOIN admin_role_assignments r ON r.admin_id=s.admin_id AND r.role='security_admin' WHERE s.session_id_hash=approval.approver_session_id_hash AND s.admin_id=approval.approver_id AND s.mfa_verified_at=approval.approver_mfa_verified_at AND s.revoked_at IS NULL AND s.expires_at>NEW.created_at) THEN RAISE EXCEPTION 'selarti budget approval invalid'; END IF;
  UPDATE admin_approvals SET consumed_at=NEW.created_at WHERE id=NEW.approval_id;
  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.validate_test_expert_campaign_prompt()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
  if new.status='active' and not exists (
    select 1 from test_expert_prompt_assets p where p.id=new.prompt_asset_id and p.version=new.prompt_asset_version
      and p.status='approved' and p.official_contract_evidence is not null
  ) then raise exception 'test expert campaign prompt is not approved'; end if;
  return new;
end $function$

CREATE OR REPLACE FUNCTION public.validate_test_expert_campaign_transition()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
  if tg_op='DELETE' then raise exception 'test expert immutable fact'; end if;
  if (old.id,old.code,old.version,old.cap_units,old.provider_calls_per_message,old.prompt_asset_id,old.prompt_asset_version,old.effective_from,old.effective_to,old.created_at)
     is distinct from (new.id,new.code,new.version,new.cap_units,new.provider_calls_per_message,new.prompt_asset_id,new.prompt_asset_version,new.effective_from,new.effective_to,new.created_at)
     or not ((old.status='inactive' and new.status='active') or (old.status='active' and new.status='retired'))
  then raise exception 'invalid test expert campaign transition'; end if;
  return new;
end $function$

CREATE OR REPLACE FUNCTION public.validate_test_expert_prompt_transition()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
  if tg_op='DELETE' then raise exception 'test expert immutable fact'; end if;
  if (old.id,old.asset_key,old.version,old.sha256,old.source_path,old.official_contract_evidence,old.created_at)
     is distinct from (new.id,new.asset_key,new.version,new.sha256,new.source_path,new.official_contract_evidence,new.created_at)
     or not ((old.status='inactive' and new.status='approved') or (old.status='approved' and new.status='retired'))
  then raise exception 'invalid test expert prompt transition'; end if;
  return new;
end $function$
